def _decorators_above_def(py_path: "Path", func_name: str) -> list[str]:
    """Trả list dòng decorator (`@...`, stripped) LIVE ngay trên `def <func_name>` trong file
    nguồn (bỏ dòng trống/comment xen giữa). Dùng cho guard NOT-FLIPPED: assert dạng decorator
    @source thay vì diff working-tree (hermetic — immune với endpoint KHÁC thêm sau; xem QA vòng 3
    LL-TEST-27/false-positive). Rỗng nếu KHÔNG tìm thấy def (caller assert nên fail rõ)."""
    lines = py_path.read_text(encoding="utf-8").splitlines()
    def_idx = next((i for i, ln in enumerate(lines)
                    if ln.startswith(f"def {func_name}(") or ln.startswith(f"def {func_name} ")), None)
    if def_idx is None:
        return []
    decs: list[str] = []
    j = def_idx - 1
    while j >= 0:
        s = lines[j].strip()
        if s.startswith("@"):
            decs.append(s)
            j -= 1
            continue
        if s == "" or s.startswith("#"):
            j -= 1
            continue
        break
    return decs

