def _depreciation_schedule_select_options(fieldname: str) -> list[str]:
    """Đọc Select options THẬT của 1 field @ac_asset_depreciation_schedule.json (grounding chống-bịa)."""
    doc = json.loads(_ASSET_DEPRECIATION_SCHEDULE_DOCTYPE_JSON.read_text(encoding="utf-8"))
    for f in doc.get("fields") or []:
        if f.get("fieldname") == fieldname:
            return [o for o in (f.get("options") or "").split("\n") if o != ""]
    return []


