# ── TC-MOB-OAS-SCANQR-PARAM — CR-05 typed-query-param cho 2 scan-QR read path ──────────────────
#   resolveQrToken (?token=) + getAssetScanInfo (?token=/?name=) TRƯỚC vòng CHỈ mô tả param trong
#   prose `description` (path block KHÔNG có `parameters:`) ⇒ generated typescript-axios KHÔNG sinh
#   query param typed → CORE-DEV phải cast qua axios request options.params. Bồi `parameters:` TYPED
#   (in:query, required:false, schema.type:string) ⇒ codegen phơi param typed, bỏ options cast.
#   required:false BẮT BUỘC — backend default "" (imm00.py:605/648) + OR-resolve (token HOẶC name;
#   required 1 lane sẽ PHÁ lane kia). CONTRACT-ONLY (handler+service LIVE @source — KHÔNG reload/
#   migrate). Params-only: 0 schema drift, 0 path/opId mới, 200-shape oneOf GIỮ NGUYÊN. ADR-MOBILE-034.
_SCANQR_RESOLVE_PATH = "/api/method/assetcore.api.imm00.resolve_qr_token"
_SCANQR_INFO_PATH = "/api/method/assetcore.api.imm00.get_asset_scan_info"


class TestMobileScanQrTypedParams(unittest.TestCase):
    """CR-05 — 2 scan-QR read path khai query param TYPED (bỏ prose-only + axios options cast).

    Grounded chữ-ký LIVE @source (introspect argspec):
      - resolve_qr_token(token: str = "")             → 1 param {token}       imm00.py:605
      - get_asset_scan_info(token: str = "", name="")  → 2 param {token,name}  imm00.py:648
    TẤT CẢ required:false (backend default "" + OR-resolve — required 1 lane phá lane kia).
    Params-only: 0 schema drift, 0 path/opId mới, 200-shape oneOf [<Envelope>, Error] GIỮ NGUYÊN.
    """

    @classmethod
    def setUpClass(cls):
        cls.spec = _load_spec() if _MOBILE_YAML.exists() else None

    def setUp(self):
        if self.spec is None:
            self.skipTest("Thiếu yaml mobile spec.")

    def _params(self, path):
        get = (((self.spec.get("paths") or {}).get(path) or {}).get("get") or {})
        return get, [p for p in (get.get("parameters") or []) if isinstance(p, dict)]

    def test_mob_oas_scanqr_a_resolve_exactly_one_token_param(self):
        """(a) [RED→GREEN] resolveQrToken có khối `parameters:` khai ĐÚNG 1 param `token`
        in:query required:false schema.type:string (imm00.py:605). RED-before: parameters key VẮNG."""
        get, params = self._params(_SCANQR_RESOLVE_PATH)
        self.assertIn(
            "parameters", get,
            "resolveQrToken PHẢI có khối `parameters:` (CR-05 — KHÔNG prose-only; codegen sinh typed).",
        )
        names = [p.get("name") for p in params]
        self.assertEqual(names, ["token"], f"resolveQrToken PHẢI khai ĐÚNG 1 param `token`: {names}.")
        p = params[0]
        self.assertEqual(p.get("in"), "query", "token PHẢI in:query (RPC no-template).")
        self.assertIs(
            p.get("required"), False,
            "token PHẢI required:false (backend default '' imm00.py:605 — OR-resolve, KHÔNG required:true).",
        )
        self.assertEqual((p.get("schema") or {}).get("type"), "string", "token PHẢI schema.type:string.")

    def test_mob_oas_scanqr_b_scaninfo_exactly_token_and_name_params(self):
        """(b) getAssetScanInfo có khối `parameters:` khai ĐÚNG 2 param {token,name} cả hai in:query
        required:false schema.type:string (imm00.py:648)."""
        get, params = self._params(_SCANQR_INFO_PATH)
        self.assertIn("parameters", get, "getAssetScanInfo PHẢI có khối `parameters:` (CR-05).")
        by = {p.get("name"): p for p in params}
        self.assertEqual(
            set(by.keys()), {"token", "name"},
            f"getAssetScanInfo PHẢI khai ĐÚNG 2 param {{token,name}}: {sorted(by)}.",
        )
        for nm in ("token", "name"):
            p = by[nm]
            self.assertEqual(p.get("in"), "query", f"{nm} PHẢI in:query.")
            self.assertIs(
                p.get("required"), False,
                f"{nm} PHẢI required:false (backend default '' imm00.py:648 — OR-resolve).",
            )
            self.assertEqual((p.get("schema") or {}).get("type"), "string", f"{nm} PHẢI schema.type:string.")

    def test_mob_oas_scanqr_c_all_params_optional_or_resolve(self):
        """(c) [RED→GREEN] TẤT CẢ 3 param (token/resolve + token,name/scan) required:false — giữ
        OR-resolve (required 1 lane phá lane kia). RED-before: parameters key VẮNG ⇒ collected == 0."""
        collected = []
        for path in (_SCANQR_RESOLVE_PATH, _SCANQR_INFO_PATH):
            _, params = self._params(path)
            collected.extend(params)
        self.assertEqual(
            len(collected), 3,
            f"PHẢI đúng 3 param scan-QR (1 resolve + 2 scan): {len(collected)} (RED-before nếu prose-only).",
        )
        required_true = [p.get("name") for p in collected if p.get("required") is True]
        self.assertEqual(
            required_true, [],
            f"KHÔNG param nào required:true (OR-resolve — backend default ''): {required_true}.",
        )

    def test_mob_oas_scanqr_d_params_subset_live_signature(self):
        """(d) Param khai == chữ-ký backend LIVE (introspect argspec) — 0 bịa, 0 thiếu:
        resolve_qr_token=={token}, get_asset_scan_info=={token,name} (imm00.py:605/648)."""
        mod = importlib.import_module("assetcore.api.imm00")
        for path, fnname, expect in (
            (_SCANQR_RESOLVE_PATH, "resolve_qr_token", {"token"}),
            (_SCANQR_INFO_PATH, "get_asset_scan_info", {"token", "name"}),
        ):
            fn = getattr(mod, fnname, None)
            self.assertIsNotNone(fn, f"Thiếu hàm whitelist LIVE: assetcore.api.imm00.{fnname}")
            live = {
                k for k, v in inspect.signature(fn).parameters.items()
                if v.kind in (v.POSITIONAL_OR_KEYWORD, v.KEYWORD_ONLY)
            }
            self.assertEqual(live, expect, f"{fnname} live-sig PHẢI == {expect} (đề mục grounded): {live}.")
            _, params = self._params(path)
            declared = {p.get("name") for p in params}
            self.assertEqual(
                declared, expect,
                f"{fnname} param khai PHẢI == live-sig {expect} (0 bịa/0 thiếu): {declared}.",
            )
            self.assertTrue(declared <= live, f"{fnname} param khai {declared} PHẢI ⊆ live-sig {live} (KHÔNG bịa).")

    def test_mob_oas_scanqr_e_200_shape_unchanged_oneof(self):
        """(e) Params-only: 200-shape oneOf [<Envelope>, Error] GIỮ NGUYÊN + envelope/Error closed —
        0 schema drift, 0 path/opId mới (regression guard chống params-edit làm lệch response)."""
        schemas = (self.spec.get("components") or {}).get("schemas") or {}
        for path, env_name in (
            (_SCANQR_RESOLVE_PATH, "QrResolveEnvelope"),
            (_SCANQR_INFO_PATH, "AssetScanInfoEnvelope"),
        ):
            op = (((self.spec.get("paths") or {}).get(path) or {}).get("get") or {})
            schema200 = _200_schema(op.get("responses") or {})
            refs = [b.get("$ref") for b in (schema200.get("oneOf") or []) if isinstance(b, dict)]
            self.assertIn(
                f"#/components/schemas/{env_name}", refs,
                f"{path} 200 oneOf PHẢI GIỮ nhánh {env_name}: {refs}.",
            )
            self.assertIn(_ERROR_SCHEMA_REF, refs, f"{path} 200 oneOf PHẢI GIỮ nhánh Error: {refs}.")
            self.assertNotIn("discriminator", schema200, f"{path} 200 KHÔNG discriminator (Decision-B).")
            self.assertIs(
                (schemas.get(env_name) or {}).get("additionalProperties"), False,
                f"{env_name} PHẢI GIỮ closed (additionalProperties:false).",
            )
        self.assertIs(
            (schemas.get("Error") or {}).get("additionalProperties"), False,
            "Error PHẢI GIỮ closed (params-only KHÔNG đụng schema).",
        )


