    def test_mob_oas_downtime_g_grounding_props_match_source(self):
        """(g) GROUNDING anti-bịa (đọc TRỰC TIẾP imm00.py): set(top-level props) == set(_ok(...) keys
        @2936-2944) VÀ set(AssetDowntimeLog fields) == set(get_all fields @2915-2916). Chống schema bịa
        lệch return-dict / get_all fields thật."""
        src_path = _REPO_ROOT / "assetcore" / "api" / "imm00.py"
        fn_src = _extract_named_function_source(src_path.read_text(encoding="utf-8"), "get_asset_downtime_metrics")
        self.assertIsNotNone(fn_src, "Thiếu hàm get_asset_downtime_metrics trong imm00.py — grounding vô nghĩa.")
        tree = ast.parse(fn_src)
        ok_keys = None
        getall_fields = None
        for node in ast.walk(tree):
            if isinstance(node, ast.Call):
                func = node.func
                fname = func.id if isinstance(func, ast.Name) else getattr(func, "attr", None)
                if fname == "_ok" and node.args and isinstance(node.args[0], ast.Dict):
                    ok_keys = {k.value for k in node.args[0].keys if isinstance(k, ast.Constant)}
                if fname == "get_all":
                    for kw in node.keywords:
                        if kw.arg == "fields" and isinstance(kw.value, ast.List):
                            getall_fields = {e.value for e in kw.value.elts if isinstance(e, ast.Constant)}
        self.assertIsNotNone(ok_keys, "KHÔNG tìm được _ok({...}) dict-literal @source — grounding vô nghĩa.")
        self.assertIsNotNone(getall_fields, "KHÔNG tìm được get_all(..., fields=[...]) @source — grounding vô nghĩa.")
        self.assertEqual(
            ok_keys, _ASSET_DOWNTIME_METRICS_PROPS,
            f"GROUNDING: set(_ok keys @imm00.py:2936-2944)={sorted(ok_keys)} PHẢI == 8 top-level prop schema (anti-bịa).",
        )
        # schema top-level props THẬT == _ok keys @source.
        schema_props = set((self._schemas().get(_ASSET_DOWNTIME_METRICS_SCHEMA) or {}).get("properties") or {})
        self.assertEqual(schema_props, ok_keys, "schema AssetDowntimeMetrics props PHẢI == _ok keys @source.")
        self.assertEqual(
            getall_fields, _ASSET_DOWNTIME_LOG_PROPS,
            f"GROUNDING: set(get_all fields @imm00.py:2915-2916)={sorted(getall_fields)} PHẢI == 8 AssetDowntimeLog field (anti-bịa).",
        )
        log_props = set((self._schemas().get(_ASSET_DOWNTIME_LOG_SCHEMA) or {}).get("properties") or {})
        self.assertEqual(log_props, getall_fields, "schema AssetDowntimeLog props PHẢI == get_all fields @source.")

