    def test_mob_oas_verifychain_e_types_verbatim_grounding_return_shapes(self):
        """(e) property types VERBATIM: valid=boolean (bool THẬT), count=integer, broken_at=string nullable,
        index=integer nullable. GROUNDING anti-bịa (đọc TRỰC-TIẾP utils/lifecycle.py verify_audit_chain):
        UNION(return-dict keys)==props VÀ INTERSECTION(return-dict keys)==required."""
        props = (self._schemas().get(_ASSET_VERIFY_CHAIN_SCHEMA) or {}).get("properties") or {}
        for pname, expected_type in _ASSET_VERIFY_CHAIN_TYPES.items():
            self.assertEqual(
                (props.get(pname) or {}).get("type"), expected_type,
                f"{pname} PHẢI type {expected_type} (grounded return-shape @utils/lifecycle.py:112/114).",
            )
        # valid = bool THẬT ⇒ type:boolean (KHÁC Check→int enum[0,1]; KHÔNG int-vs-bool trap LL-BE-52).
        valid = props.get("valid") or {}
        self.assertEqual(valid.get("type"), "boolean", "valid PHẢI boolean (Python bool THẬT True/False, KHÔNG Check-int).")
        self.assertNotIn("enum", valid, "valid KHÔNG enum[0,1] (bool THẬT ≠ Check-int).")
        # broken_at/index nullable:true (có type sibling ⇒ né redocly nullable-type-sibling lint test_mob_oas_08).
        for pname in _ASSET_VERIFY_CHAIN_NULLABLE:
            self.assertTrue(
                (props.get(pname) or {}).get("nullable"),
                f"{pname} PHẢI nullable:true (OPTIONAL — chỉ emit khi valid=false).",
            )
            self.assertIn("type", props.get(pname) or {}, f"{pname} PHẢI có `type` sibling cho nullable (redocly lint).")
        # count NON-null (LUÔN len(rows) — KHÔNG nullable).
        self.assertNotEqual((props.get("count") or {}).get("nullable"), True, "count PHẢI non-null (LUÔN len(rows)).")
        # GROUNDING — đọc TRỰC-TIẾP verify_audit_chain builder (dict-literal ở lifecycle.py KHÔNG imm00.verify_chain).
        dicts = self._verify_audit_chain_return_dicts()
        self.assertGreaterEqual(len(dicts), 2, "verify_audit_chain PHẢI có ≥2 return-dict-literal (pass/fail) — grounding vô nghĩa.")
        union = set().union(*dicts)
        intersection = set(dicts[0]).intersection(*dicts[1:])
        self.assertEqual(
            union, _ASSET_VERIFY_CHAIN_PROPS,
            f"GROUNDING: UNION(return-dict keys @lifecycle.py)={sorted(union)} PHẢI == 4 prop schema (anti-bịa).",
        )
        self.assertEqual(
            intersection, set(_ASSET_VERIFY_CHAIN_REQUIRED),
            f"GROUNDING: INTERSECTION(return-dict keys @lifecycle.py)={sorted(intersection)} PHẢI == required {_ASSET_VERIFY_CHAIN_REQUIRED} (always-emit).",
        )
        # schema top-level props THẬT == UNION @source.
        self.assertEqual(set(props.keys()), union, "schema AssetVerifyChain props PHẢI == UNION return-dict keys @source.")

