    @classmethod
    def setUpClass(cls):
        cls.spec = _load_spec() if _MOBILE_YAML.exists() else None

    def _op(self):
        return ((self.spec.get("paths") or {}).get(_ASSET_DEPRECIATION_SCHEDULE_PATH) or {}).get("get") or {}

    def _schemas(self):
        return (self.spec.get("components") or {}).get("schemas") or {}

    def _depreciation_lists_by_doctype(self):
        """{doctype: set(field-list)} của get_all/get_value trong get_depreciation_schedule (grounding per-schema
        anti-bịa): doctype = str positional đầu; field-list = List positional HOẶC fields= kwarg. get_all(
        'AC Asset Depreciation Schedule', fields=[...9 row]) + get_value('AC Asset', name, [...9 info])."""
        src_path = _REPO_ROOT / "assetcore" / "api" / "imm00.py"
        fn_src = _extract_named_function_source(src_path.read_text(encoding="utf-8"), "get_depreciation_schedule")
        self.assertIsNotNone(fn_src, "Thiếu hàm get_depreciation_schedule trong api/imm00.py — grounding vô nghĩa.")
        tree = ast.parse(fn_src)
        result: dict[str, set] = {}
        for node in ast.walk(tree):
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) \
                    and node.func.attr in ("get_all", "get_value"):
                dt = None
                for a in node.args:
                    if isinstance(a, ast.Constant) and isinstance(a.value, str):
                        dt = a.value
                        break
                flds: set = set()
                candidates = list(node.args) + [kw.value for kw in node.keywords if kw.arg == "fields"]
                for arg in candidates:
                    if isinstance(arg, ast.List):
                        for el in arg.elts:
                            if isinstance(el, ast.Constant) and isinstance(el.value, str):
                                flds.add(el.value)
                if dt and flds:
                    result[dt] = result.get(dt, set()) | flds
        return result

    def _depreciation_dict_keysets(self):
        """List[frozenset] các key-set của MỌI ast.Dict literal trong get_depreciation_schedule (summary + _ok
        wrapper + filters). summary/wrapper key-set PHẢI xuất-hiện VERBATIM như 1 dict literal @source."""
        src_path = _REPO_ROOT / "assetcore" / "api" / "imm00.py"
        fn_src = _extract_named_function_source(src_path.read_text(encoding="utf-8"), "get_depreciation_schedule")
        tree = ast.parse(fn_src)
        keysets = []
        for node in ast.walk(tree):
            if isinstance(node, ast.Dict):
                ks = frozenset(
                    k.value for k in node.keys
                    if isinstance(k, ast.Constant) and isinstance(k.value, str)
                )
                if ks:
                    keysets.append(ks)
        return keysets

    def test_mob_oas_depsched_a_path_opid_tag_count_70(self):
        """(a) yaml OK; path-count == 70 (69→70); path GET-ONLY opId getAssetDepreciationSchedule tag asset."""
