    def test_mob_oas_depsched_h_zero_footprint_siblings_scoped_handler(self):
        """(h) ZERO-FOOTPRINT/no-drift: naming-guard 5 schema mới; 4 sibling CR-11a/b/c/d BẤT BIẾN; 0 dangling
        $ref; SCOPED-HANDLER get_depreciation_schedule @api/imm00.py:2962 byte-identical HEAD↔working."""
        schemas = self._schemas()
        new_names = {
            _ASSET_DEPRECIATION_SCHEDULE_SCHEMA, _ASSET_DEPRECIATION_SCHEDULE_ENVELOPE_SCHEMA,
            _DEPRECIATION_SCHEDULE_ROW_SCHEMA, _DEPRECIATION_SCHEDULE_SUMMARY_SCHEMA,
            _ASSET_DEPRECIATION_INFO_SCHEMA,
        }
        self.assertTrue(new_names.issubset(set(schemas)), "5 schema CR-11e PHẢI TỒN TẠI.")
        # naming-guard: prefix AssetDepreciation* == {AssetDepreciationSchedule, ...Envelope, ...Info} (3 tên).
        adep_prefixed = {n for n in schemas if n.startswith("AssetDepreciation")}
        self.assertEqual(
            adep_prefixed,
            {_ASSET_DEPRECIATION_SCHEDULE_SCHEMA, _ASSET_DEPRECIATION_SCHEDULE_ENVELOPE_SCHEMA, _ASSET_DEPRECIATION_INFO_SCHEMA},
            f"CHỈ 3 schema prefix AssetDepreciation (KHÔNG mọc thừa): {sorted(adep_prefixed)}.",
        )
        dep_prefixed = {n for n in schemas if n.startswith("DepreciationSchedule")}
        self.assertEqual(
            dep_prefixed, {_DEPRECIATION_SCHEDULE_ROW_SCHEMA, _DEPRECIATION_SCHEDULE_SUMMARY_SCHEMA},
            f"CHỈ 2 schema prefix DepreciationSchedule (KHÔNG mọc thừa): {sorted(dep_prefixed)}.",
        )
        # 4 sibling CR-11a/b/c/d BẤT BIẾN.
        kpi = schemas.get(_ASSET_KPI_SCHEMA) or {}
        self.assertEqual(set(kpi.get("properties") or {}), _ASSET_KPI_PROPS, "AssetKpi props PHẢI BẤT BIẾN 12 (CR-11e KHÔNG đụng).")
        self.assertEqual(sorted(kpi.get("required") or []), sorted(_ASSET_KPI_REQUIRED), "AssetKpi required PHẢI BẤT BIẾN 5.")
        dm = schemas.get(_ASSET_DOWNTIME_METRICS_SCHEMA) or {}
        self.assertEqual(set(dm.get("properties") or {}), _ASSET_DOWNTIME_METRICS_PROPS, "AssetDowntimeMetrics props PHẢI BẤT BIẾN 8.")
        vc = schemas.get(_ASSET_VERIFY_CHAIN_SCHEMA) or {}
        self.assertEqual(set(vc.get("properties") or {}), _ASSET_VERIFY_CHAIN_PROPS, "AssetVerifyChain props PHẢI BẤT BIẾN 4.")
        self.assertEqual(sorted(vc.get("required") or []), _ASSET_VERIFY_CHAIN_REQUIRED, "AssetVerifyChain required PHẢI BẤT BIẾN 2.")
        co = schemas.get(_ASSET_COMMISSIONING_ORIGIN_SCHEMA) or {}
        self.assertEqual(set(co.get("properties") or {}), _ASSET_COMMISSIONING_ORIGIN_PROPS, "AssetCommissioningOrigin props PHẢI BẤT BIẾN 2.")
        # 0 dangling $ref toàn yaml sau bồi 5 schema.
        dangling = sorted({r for r in _collect_refs(self.spec) if not _resolve_pointer(r, self.spec)})
        self.assertEqual(dangling, [], f"PHẢI 0 dangling $ref sau bồi getAssetDepreciationSchedule: {dangling}")
