    def test_mob_oas_attachphoto_d_200_oneof_route_by_value(self):
        """(d) 200 = oneOf [AttachIncidentPhotoEnvelope, Error] ở response-content-schema (route-by-VALUE,
        0 discriminator; 2 branch closed, success enum disjoint [true]/[false])."""
        resp200 = ((self._op().get("responses") or {}).get("200") or {})
        schema = (((resp200.get("content") or {}).get("application/json") or {}).get("schema") or {})
        self.assertNotIn("discriminator", schema, "200 KHÔNG discriminator (route-by-VALUE body.success, §5c).")
        one_of = schema.get("oneOf") or []
        refs = {m.get("$ref") for m in one_of if isinstance(m, dict)}
        self.assertEqual(
            refs, {_ATTACH_INCIDENT_PHOTO_ENVELOPE_SCHEMA_REF, _ERROR_SCHEMA_REF},
            f"200.oneOf PHẢI = [AttachIncidentPhotoEnvelope, Error]: {sorted(refs)}",
        )
        self.assertEqual(len(one_of), 2, "200.oneOf PHẢI ĐÚNG 2 nhánh (Env + Error).")
        schemas = self._schemas()
        env = schemas.get(_ATTACH_INCIDENT_PHOTO_ENVELOPE_SCHEMA) or {}
        err = schemas.get("Error") or {}
        self.assertEqual(env.get("additionalProperties"), False, "AttachIncidentPhotoEnvelope PHẢI closed.")
        self.assertEqual(err.get("additionalProperties"), False, "Error PHẢI closed (§5c).")
        env_succ = ((env.get("properties") or {}).get("success") or {}).get("enum")
        err_succ = ((err.get("properties") or {}).get("success") or {}).get("enum")
