    def test_mob_oas_attachrepairphoto_j_naming_collision_guard_and_contract_only(self):
        """(j) naming/collision guard 3-WAY — 3 schema AttachRepairChecklistPhoto{Request,Response,Envelope}
        distinct, KHÔNG trùng/đụng AttachPmChecklistPhoto* LẪN AttachIncidentPhoto*; AttachRepairChecklistPhoto*
        ∩ AttachPmChecklistPhoto* == ∅ ∧ ∩ AttachIncidentPhoto* == ∅. CONTRACT-ONLY anti-false-green: handler LIVE
        @source (resolvable + whitelisted + POST-only) ⇒ backend đã live, vòng này PURE-YAML+test ⇒ KHÔNG
        reload/migrate.

        Anti-false-green: đổi decorator @source thành bare @whitelist → (b)/(j) FAIL; xoá hàm → (c)/(j)
        FAIL; copy AttachPmChecklistPhoto/AttachIncidentPhoto schema → naming-collision FAIL đây."""
        schemas = self._schemas()
        repair_names = {
            _ATTACH_REPAIR_CHECKLIST_PHOTO_REQUEST_SCHEMA,
            _ATTACH_REPAIR_CHECKLIST_PHOTO_RESPONSE_SCHEMA,
            _ATTACH_REPAIR_CHECKLIST_PHOTO_ENVELOPE_SCHEMA,
        }
        pm_names = {
            _ATTACH_PM_CHECKLIST_PHOTO_REQUEST_SCHEMA,
            _ATTACH_PM_CHECKLIST_PHOTO_RESPONSE_SCHEMA,
            _ATTACH_PM_CHECKLIST_PHOTO_ENVELOPE_SCHEMA,
        }
        incident_names = {
            _ATTACH_INCIDENT_PHOTO_REQUEST_SCHEMA,
            _ATTACH_INCIDENT_PHOTO_RESPONSE_SCHEMA,
            _ATTACH_INCIDENT_PHOTO_ENVELOPE_SCHEMA,
        }
        self.assertEqual(repair_names & pm_names, set(), "AttachRepairChecklistPhoto* ∩ AttachPmChecklistPhoto* PHẢI == ∅ (naming guard).")
        self.assertEqual(repair_names & incident_names, set(), "AttachRepairChecklistPhoto* ∩ AttachIncidentPhoto* PHẢI == ∅ (naming guard 3-way).")
        for n in repair_names:
            self.assertIn(n, schemas, f"Thiếu schema {n} (3 schema Repair RIÊNG).")
        for n in pm_names:
            self.assertIn(n, schemas, f"Schema PM {n} PHẢI VẪN tồn tại (KHÔNG đụng/xoá — additive).")
        for n in incident_names:
            self.assertIn(n, schemas, f"Schema incident {n} PHẢI VẪN tồn tại (KHÔNG đụng/xoá — additive).")
        # Prefix-collision: schema-set AttachRepairChecklistPhoto* PHẢI EXACT 3 + disjoint prefix pm/incident.
        repair_prefix = {s for s in schemas if s.startswith("AttachRepairChecklistPhoto")}
        pm_prefix = {s for s in schemas if s.startswith("AttachPmChecklistPhoto")}
        inc_prefix = {s for s in schemas if s.startswith("AttachIncidentPhoto")}
        self.assertEqual(repair_prefix, repair_names, f"AttachRepairChecklistPhoto* schema-set PHẢI EXACT 3 (got {sorted(repair_prefix)}).")
        self.assertEqual(repair_prefix & pm_prefix, set(), "prefix-set AttachRepairChecklistPhoto* ∩ AttachPmChecklistPhoto* PHẢI == ∅.")
        self.assertEqual(repair_prefix & inc_prefix, set(), "prefix-set AttachRepairChecklistPhoto* ∩ AttachIncidentPhoto* PHẢI == ∅.")
        # CONTRACT-ONLY — handler LIVE @source (backend live phiên BE song song, uncommitted). pure-yaml ⇒ KHÔNG reload.
        import frappe  # lazy — cần frappe init (bench run-tests có sẵn).
        dotted = _dotted_of(_ATTACH_REPAIR_CHECKLIST_PHOTO_PATH)
        fn = frappe.get_attr(dotted)
        self.assertTrue(callable(fn), f"{dotted} PHẢI resolve → callable LIVE @source.")
        self.assertIn(fn, frappe.whitelisted, f"{dotted} PHẢI @whitelist (frappe.whitelisted) — backend live.")
        allowed = _allowed_http_methods_for(dotted)
        self.assertEqual(
            allowed, {"POST"},
            f"{dotted} PHẢI POST-only @source (methods=['POST'] @api/imm09.py:57) ⇒ backend live, KHÔNG reload. got {sorted(allowed)}",
        )


