        self.assertEqual(
            sch_props, set(params.keys()),
            f"SendToLabRequest props PHẢI KHỚP 1:1 live signature: props={sorted(sch_props)} sig={sorted(params.keys())}.",
        )
        self.assertIs(params["name"].default, inspect.Parameter.empty, "param `name` PHẢI KHÔNG default (required).")
        for p in ("sent_date", "lab_supplier", "lab_contract_ref"):
            self.assertIsNone(params[p].default, f"param `{p}` default PHẢI None (optional nullable @api/imm11.py:169-170).")

