    def test_mob_oas_recvtransfer_i_naming_guard_and_live_sig(self):
        """(i) naming-guard — 3 ReceiveTransfer* component MỚI KHÔNG trùng sibling (Transfer* read /
        ReceiveCertificate* / SendToLab* / CancelCalibration*); live-sig parity
        inspect.signature(imm00.receive_transfer) == request props (2-param; name required + handover_notes
        default `""` KHÔNG None)."""
        schemas = self._schemas()
        # 3 component ReceiveTransfer* PHẢI tồn tại + là DUY NHẤT tập ReceiveTransfer* (naming-guard ∩ ∅).
        recv_transfer_schemas = {n for n in schemas if n.startswith("ReceiveTransfer")}
        self.assertEqual(
            recv_transfer_schemas,
            {_RECEIVE_TRANSFER_REQUEST_SCHEMA, _RECEIVE_TRANSFER_RESPONSE_SCHEMA, _RECEIVE_TRANSFER_ENVELOPE_SCHEMA},
            f"ReceiveTransfer* schema PHẢI ĐÚNG 3 component MỚI (naming-guard ∩ ∅), got {sorted(recv_transfer_schemas)}.",
        )
        # disjoint với Transfer* read (getTransfer/listTransfers) + ReceiveCertificate* + SendToLab*.
        for sib in (
            "TransferDetail", "TransferDetailEnvelope", "TransferListItem", "TransferListEnvelope",
            _RECEIVE_CERTIFICATE_REQUEST_SCHEMA, _RECEIVE_CERTIFICATE_RESPONSE_SCHEMA, _RECEIVE_CERTIFICATE_ENVELOPE_SCHEMA,
            _SEND_TO_LAB_REQUEST_SCHEMA, _SEND_TO_LAB_RESPONSE_SCHEMA, _SEND_TO_LAB_ENVELOPE_SCHEMA,
            _CANCEL_CALIBRATION_REQUEST_SCHEMA,
        ):
            self.assertNotIn(sib, recv_transfer_schemas, f"naming-guard: {sib} KHÔNG được ∈ tập ReceiveTransfer*.")
        # live-sig parity — signature LIVE == request props (chống drift contract↔source).
        from assetcore.api import imm00  # lazy.
        fn = getattr(imm00, "receive_transfer", None)
        self.assertIsNotNone(fn, "Thiếu hàm whitelist LIVE: imm00.receive_transfer.")
        params = inspect.signature(fn).parameters
        self.assertEqual(
            set(params.keys()), _RECEIVE_TRANSFER_SIG_PARAMS,
            f"signature LIVE PHẢI EXACT {_RECEIVE_TRANSFER_SIG_PARAMS}, got {sorted(params.keys())}.",
        )
        sch_props = set((schemas.get(_RECEIVE_TRANSFER_REQUEST_SCHEMA) or {}).get("properties") or {})
        self.assertEqual(
            sch_props, set(params.keys()),
            f"ReceiveTransferRequest props PHẢI KHỚP 1:1 live signature: props={sorted(sch_props)} sig={sorted(params.keys())}.",
        )
        self.assertIs(params["name"].default, inspect.Parameter.empty, "param `name` PHẢI KHÔNG default (required).")
        self.assertEqual(
            params["handover_notes"].default, "",
            "param `handover_notes` default PHẢI `''` empty-string (@api/imm00.py:2601 — KHÔNG None, KHÁC sendToLab optionals).",
        )

