    def test_mob_oas_apprvtransfer_i_naming_guard_and_live_sig(self):
        """(i) naming-guard — 3 ApproveTransfer* component MỚI KHÔNG trùng sibling (Transfer* read /
        ReceiveTransfer* / SendToLab* / CancelCalibration*); live-sig parity
        inspect.signature(imm00.approve_transfer) == request props (1-param; name required KHÔNG default —
        KHÁC receiveTransfer 2-param)."""
        schemas = self._schemas()
        # 3 component ApproveTransfer* PHẢI tồn tại + là DUY NHẤT tập ApproveTransfer* (naming-guard ∩ ∅).
        apprv_schemas = {n for n in schemas if n.startswith("ApproveTransfer")}
        self.assertEqual(
            apprv_schemas,
            {_APPROVE_TRANSFER_REQUEST_SCHEMA, _APPROVE_TRANSFER_RESPONSE_SCHEMA, _APPROVE_TRANSFER_ENVELOPE_SCHEMA},
            f"ApproveTransfer* schema PHẢI ĐÚNG 3 component MỚI (naming-guard ∩ ∅), got {sorted(apprv_schemas)}.",
        )
        # disjoint với Transfer* read + ReceiveTransfer* + SendToLab* + CancelCalibration*.
        for sib in (
            "TransferDetail", "TransferDetailEnvelope", "TransferListItem", "TransferListEnvelope",
            _RECEIVE_TRANSFER_REQUEST_SCHEMA, _RECEIVE_TRANSFER_RESPONSE_SCHEMA, _RECEIVE_TRANSFER_ENVELOPE_SCHEMA,
            _SEND_TO_LAB_REQUEST_SCHEMA, _SEND_TO_LAB_RESPONSE_SCHEMA,
            _CANCEL_CALIBRATION_REQUEST_SCHEMA, _CANCEL_CALIBRATION_RESPONSE_SCHEMA,
        ):
            self.assertNotIn(sib, apprv_schemas, f"naming-guard: {sib} KHÔNG được ∈ tập ApproveTransfer*.")
        # live-sig parity — signature LIVE == request props (chống drift contract↔source).
        from assetcore.api import imm00  # lazy.
        fn = getattr(imm00, "approve_transfer", None)
        self.assertIsNotNone(fn, "Thiếu hàm whitelist LIVE: imm00.approve_transfer.")
        params = inspect.signature(fn).parameters
        self.assertEqual(
            set(params.keys()), _APPROVE_TRANSFER_SIG_PARAMS,
            f"signature LIVE PHẢI EXACT {_APPROVE_TRANSFER_SIG_PARAMS}, got {sorted(params.keys())}.",
        )
        sch_props = set((schemas.get(_APPROVE_TRANSFER_REQUEST_SCHEMA) or {}).get("properties") or {})
        self.assertEqual(
            sch_props, set(params.keys()),
            f"ApproveTransferRequest props PHẢI KHỚP 1:1 live signature: props={sorted(sch_props)} sig={sorted(params.keys())}.",
        )
        self.assertIs(params["name"].default, inspect.Parameter.empty, "param `name` PHẢI KHÔNG default (required).")
        # 1-param — KHÔNG optional (KHÁC receiveTransfer handover_notes 2-param).
        self.assertEqual(
            len(params), 1,
            "approve_transfer PHẢI 1-param (name) — KHÔNG optional body (@api/imm00.py:2583, KHÁC receiveTransfer 2-param handover_notes).",
        )

