    def test_mob_oas_rejtransfer_g_response_slots_403_reachable_422_three_branch(self):
        """(g) slot {200,401,403}; 401 Unauthorized401; 403 SINGLE-SHAPE Forbidden REACHABLE (cap
        commissioning.submit @services/imm00.py:2651 raise PermissionError NGOÀI except-ValidationError →
        HTTP-403 THẬT dispatcher-style — GIỐNG approveTransfer KHÁC receiveTransfer); op.description GHI RÕ note
        REACHABLE + cap; ⚠️ ANTI-DRIFT Error.http_status enum ⊇ {422} (422-uniform CẢ 3 NHÁNH: not-found
        @:2649 + rejection_reason thiếu/<5 @:2653-2654 [NHÁNH 422 THỨ-3] + wrong-status @:2657-2658; op.description
        ghi rõ nhánh rejection_reason)."""
        op = self._op()
        resps = (op.get("responses") or {})
        self.assertEqual(
            sorted(resps.keys()), ["200", "401", "403"],
            f"response slot PHẢI CHỈ {{200,401,403}} (422 in-handler trên HTTP-200 nhánh Error): {sorted(resps.keys())}",
        )
        self.assertEqual((resps.get("401") or {}).get("$ref"), _UNAUTHORIZED401_RESP_REF, "401 PHẢI $ref Unauthorized401.")
        resp403 = (resps.get("403") or {})
        self.assertEqual(
            resp403.get("$ref"), _FORBIDDEN_RESP_REF,
            f"403 PHẢI $ref Forbidden SINGLE-SHAPE (reachability ≠ shape — 403 REACHABLE nhưng shape single), got {resp403.get('$ref')}.",
        )
        self.assertNotIn("oneOf", resp403, "403 KHÔNG oneOf/dual-shape (SINGLE Forbidden — reachability ≠ shape).")
        self.assertNotEqual(
            resp403.get("$ref"), _REPORT_INCIDENT_FORBIDDEN_RESP_REF,
            "rejectTransfer 403 KHÔNG dùng ReportIncidentForbidden (đó là DUAL-403 của report_incident).",
        )
        # GIỐNG approveTransfer — op.description PHẢI GHI RÕ 403 REACHABLE + cap commissioning.submit.
        desc = op.get("description") or ""
        self.assertIn("REACHABLE", desc, "op.description PHẢI ghi rõ 403 REACHABLE (cap-branch commissioning.submit trip → HTTP-403 THẬT — chống nút-chết; GIỐNG approveTransfer, KHÁC receiveTransfer dispatcher-only).")
        self.assertIn(_REJECT_TRANSFER_CAP, desc, "op.description PHẢI nêu cap `commissioning.submit` (rbac.require @services/imm00.py:2651 raise PermissionError NGOÀI except → HTTP-403 THẬT).")
        # ⚠️ NHÁNH 422 THỨ-3 mới — op.description PHẢI GHI RÕ rejection_reason (chống drift missing-branch).
        self.assertIn("rejection_reason", desc, "op.description PHẢI nêu nhánh 422 THỨ-3 rejection_reason thiếu/<5 (@services/imm00.py:2653-2654 — anti-drift missing-branch vs approve/receive 2-nhánh).")
        # ANTI-DRIFT 422-uniform — reject_transfer phát 422 cho CẢ 3 nhánh (KHÔNG 404).
        err = self._schemas().get("Error") or {}
        hs_enum = ((err.get("properties") or {}).get("http_status") or {}).get("enum") or []
        self.assertIn(422, hs_enum, f"Error.http_status enum PHẢI ⊇ {{422}} (422-uniform reject_transfer 3-nhánh): {hs_enum}.")

