    def test_mob_oas_rejtransfer_i_naming_guard_and_live_sig(self):
        """(i) naming-guard — 3 RejectTransfer* component MỚI KHÔNG trùng sibling (Transfer* read /
        ApproveTransfer* / ReceiveTransfer* / SendToLab* / CancelCalibration*); live-sig parity
        inspect.signature(imm00.reject_transfer) == request props (2-param {name, rejection_reason})."""
        schemas = self._schemas()
        # 3 component RejectTransfer* PHẢI tồn tại + là DUY NHẤT tập RejectTransfer* (naming-guard ∩ ∅).
        rej_schemas = {n for n in schemas if n.startswith("RejectTransfer")}
        self.assertEqual(
            rej_schemas,
            {_REJECT_TRANSFER_REQUEST_SCHEMA, _REJECT_TRANSFER_RESPONSE_SCHEMA, _REJECT_TRANSFER_ENVELOPE_SCHEMA},
            f"RejectTransfer* schema PHẢI ĐÚNG 3 component MỚI (naming-guard ∩ ∅), got {sorted(rej_schemas)}.",
        )
        # disjoint với Transfer* read + ApproveTransfer* + ReceiveTransfer* + SendToLab* + CancelCalibration*.
        for sib in (
            "TransferDetail", "TransferDetailEnvelope", "TransferListItem", "TransferListEnvelope",
            _APPROVE_TRANSFER_REQUEST_SCHEMA, _APPROVE_TRANSFER_RESPONSE_SCHEMA, _APPROVE_TRANSFER_ENVELOPE_SCHEMA,
            _RECEIVE_TRANSFER_REQUEST_SCHEMA, _RECEIVE_TRANSFER_RESPONSE_SCHEMA, _RECEIVE_TRANSFER_ENVELOPE_SCHEMA,
            _SEND_TO_LAB_REQUEST_SCHEMA, _SEND_TO_LAB_RESPONSE_SCHEMA,
            _CANCEL_CALIBRATION_REQUEST_SCHEMA, _CANCEL_CALIBRATION_RESPONSE_SCHEMA,
        ):
            self.assertNotIn(sib, rej_schemas, f"naming-guard: {sib} KHÔNG được ∈ tập RejectTransfer*.")
        # live-sig parity — signature LIVE == request props (chống drift contract↔source).
        from assetcore.api import imm00  # lazy.
        fn = getattr(imm00, "reject_transfer", None)
        self.assertIsNotNone(fn, "Thiếu hàm whitelist LIVE: imm00.reject_transfer.")
        params = inspect.signature(fn).parameters
        self.assertEqual(
            set(params.keys()), _REJECT_TRANSFER_SIG_PARAMS,
            f"signature LIVE PHẢI EXACT {_REJECT_TRANSFER_SIG_PARAMS}, got {sorted(params.keys())}.",
        )
        sch_props = set((schemas.get(_REJECT_TRANSFER_REQUEST_SCHEMA) or {}).get("properties") or {})
        self.assertEqual(
            sch_props, set(params.keys()),
            f"RejectTransferRequest props PHẢI KHỚP 1:1 live signature: props={sorted(sch_props)} sig={sorted(params.keys())}.",
        )
        self.assertIs(params["name"].default, inspect.Parameter.empty, "param `name` PHẢI KHÔNG default (required).")
        # 2-param {name, rejection_reason} — KHÁC approveTransfer 1-param. rejection_reason có default '' tại
        #   handler NHƯNG service ép bắt buộc runtime ⇒ contract REQUIRED (TC-c required-set).
        self.assertEqual(
            len(params), 2,
            "reject_transfer PHẢI 2-param {name, rejection_reason} (@api/imm00.py:2592, KHÁC approveTransfer 1-param).",
        )
        self.assertIn("rejection_reason", params, "reject_transfer PHẢI có param rejection_reason (@api/imm00.py:2592).")

    def test_mob_oas_rejtransfer_j_registry_resolvable_contract_only(self):
        """(j) registry-resolvable — 0 dangling $ref sau bồi; POST-only @source (registry {POST}) —
        CONTRACT-ONLY registry-resolvability (KHÔNG HEAD git-diff false-fail: handler+service reject_transfer/
        reject_transfer_request LIVE @source byte-identical HEAD↔working ⇒ diff rỗng KHÔNG có nghĩa CHƯA làm)."""
        dangling = sorted({r for r in _collect_refs(self.spec) if not _resolve_pointer(r, self.spec)})
        self.assertEqual(dangling, [], f"PHẢI 0 dangling $ref sau bồi rejectTransfer: {dangling}")
        # CONTRACT-ONLY source-truth: POST-only @registry runtime (durable, KHÔNG bám git-diff transient).
        allowed = _allowed_http_methods_for("assetcore.api.imm00.reject_transfer")
