    def test_dept_b_path_get_only_opid_mvp(self):
        """(b) path GET-ONLY, opId listDepartments camelCase UNIQUE (len(set)==57), tags, ∈ _MVP_BUSINESS_PATHS."""
        item = (self.spec.get("paths") or {}).get(_LIST_DEPARTMENTS_PATH)
        self.assertIsNotNone(item, f"Thiếu path {_LIST_DEPARTMENTS_PATH} (DEPARTMENT-REFDATA-WIRE).")
