    def test_dept_f_int_vs_bool_trap_is_group_is_active(self):
        """(f) int-vs-bool trap: is_group & is_active = integer enum[0,1] (Frappe Check-int, KHÔNG
        boolean — né Dart/Kotlin int-vs-bool crash CR-01, đối xứng IncidentOpen/sla_breached)."""
        props = (self._schema("DepartmentListItem") or {}).get("properties") or {}
        for f in ("is_group", "is_active"):
            pdef = props.get(f) or {}
            self.assertEqual(pdef.get("type"), "integer", f"{f} (Frappe Check) PHẢI type integer (KHÔNG boolean — int-vs-bool trap CR-01).")
            self.assertNotEqual(pdef.get("type"), "boolean", f"{f} KHÔNG được boolean.")
            self.assertEqual(pdef.get("enum"), [0, 1], f"{f} PHẢI enum[0,1] (Check bounded flag).")
        # 0 property nào type:boolean toàn item (anti bool-trap sweep).
        for pname, pdef in props.items():
            self.assertNotEqual(pdef.get("type"), "boolean", f"{pname} KHÔNG được type:boolean (bool-trap).")

