    def test_cat_g_check_int_enum_and_int_number_no_enum(self):
        """(g) 4 Check (default_pm_required/default_calibration_required/has_radiation/is_active) =
        integer enum[0,1] (Frappe Check-int, KHÔNG boolean — né Dart/Kotlin int-vs-bool crash CR-01).
        3 Int (default_pm_interval_days/default_calibration_interval_days/total_depreciation_months) =
        integer nullable KHÔNG enum (số ĐẾM THẬT 0..N). default_residual_value_pct (Percent) = number.
        0 property nào type:boolean (anti bool-trap sweep)."""
        props = (self._schema("AssetCategoryListItem") or {}).get("properties") or {}
        # (g1) 4 Check → integer enum[0,1].
        for f in _ASSET_CATEGORY_INT_ENUM_PROPS:
            pdef = props.get(f) or {}
            self.assertEqual(pdef.get("type"), "integer", f"{f} (Frappe Check) PHẢI type integer (KHÔNG boolean — int-vs-bool trap CR-01).")
            self.assertNotEqual(pdef.get("type"), "boolean", f"{f} KHÔNG được boolean.")
            self.assertEqual(pdef.get("enum"), [0, 1], f"{f} PHẢI enum[0,1] (Check bounded flag).")
        # (g2) 3 Int → integer nullable KHÔNG enum (số đếm THẬT 0..N — enum[0,1] cắt >1 = FAIL).
        for f in _ASSET_CATEGORY_INT_NULLABLE_PROPS:
            pdef = props.get(f) or {}
            self.assertEqual(pdef.get("type"), "integer", f"{f} (Frappe Int) PHẢI type integer.")
            self.assertNotIn("enum", pdef, f"{f} KHÔNG được khai enum (Int = số ĐẾM THẬT 0..N, KHÁC Check flag 0/1).")
        # (g3) Percent → number (KHÔNG integer — giá trị thập phân).
        pct = props.get(_ASSET_CATEGORY_NUMBER_NULLABLE_PROP) or {}
        self.assertEqual(pct.get("type"), "number", f"{_ASSET_CATEGORY_NUMBER_NULLABLE_PROP} (Percent) PHẢI type number (thập phân, KHÔNG integer).")
        # (g4) 0 property nào type:boolean toàn item (anti bool-trap sweep).
        for pname, pdef in props.items():
            self.assertNotEqual(pdef.get("type"), "boolean", f"{pname} KHÔNG được type:boolean (bool-trap).")

