        self.assertNotIn("post", get_item, "get_notification_preferences CHỈ GET (read).")
        self.assertEqual(get_item["get"].get("operationId"), "getNotificationPreferences")
        self.assertEqual(get_item["get"].get("tags"), ["notification"], "get tag == [notification].")
        set_item = paths.get(_SET_EMAIL_ENABLED_PATH) or {}
        self.assertIn("post", set_item, "set_email_enabled PHẢI có method post.")
        self.assertEqual(set_item["post"].get("operationId"), "setEmailEnabled")
        self.assertEqual(set_item["post"].get("tags"), ["notification"], "set tag == [notification].")
        # ∈ _MVP_BUSINESS_PATHS ⇒ symmetry set tự lên (không literal).
