    def test_mob_oas_alloclist_e_200_oneof_envelope_error_401(self):
        """(TC5) 200 = response-component AllocationList; content.schema = oneOf ĐÚNG 2 nhánh
        [AllocationListEnvelope, Error], 0 discriminator; nhánh success BỌC AllocationListPage
        (Envelope.data.$ref → AllocationListPage, rows-key data.data[] double-data); success enum
        disjoint [true]/[false]; 401 Unauthorized401, 403 Forbidden; status set [200,401,403]; KHÔNG requestBody."""
        op = self._op()
