        self.assertEqual((resp.get("200") or {}).get("$ref"), _ALLOCATION_LIST_RESP_REF, "200 phải trỏ AllocationList (response-component).")
        self.assertEqual((resp.get("401") or {}).get("$ref"), "#/components/responses/Unauthorized401", "401 dùng Unauthorized401 uniform (parity listCommissioning).")
        self.assertEqual((resp.get("403") or {}).get("$ref"), "#/components/responses/Forbidden", "403 GIỮ Forbidden (guest dispatcher-403; KHÔNG cap-403-branch in-handler).")
        self.assertEqual(sorted(resp.keys()), ["200", "401", "403"], "status set = [200,401,403].")
        self.assertNotIn("requestBody", op, "listAllocations là GET — KHÔNG requestBody.")
        comp_sch = self._comp_schema()
        self.assertNotIn("$ref", comp_sch, "200 content.schema KHÔNG single $ref — PHẢI oneOf [Env, Error] (Decision-B).")
        one_of = comp_sch.get("oneOf") or []
        refs = [b.get("$ref") for b in one_of if isinstance(b, dict)]
        self.assertEqual(len(one_of), 2, f"oneOf PHẢI ĐÚNG 2 nhánh [AllocationListEnvelope, Error]: {refs}")
        self.assertIn(_ALLOCATION_LIST_SCHEMA_REF, refs, f"oneOf thiếu nhánh success Env: {refs}")
        self.assertIn(_ERROR_SCHEMA_REF, refs, f"oneOf thiếu nhánh Error: {refs}")
        self.assertNotIn("discriminator", comp_sch, "KHÔNG discriminator — Decision-B closed-schema route-by-VALUE body.success.")
        env = self._schema("AllocationListEnvelope")
        err = self._schema("Error")
        self.assertIs(env.get("additionalProperties"), False, "AllocationListEnvelope closed.")
        self.assertIs(err.get("additionalProperties"), False, "Error closed.")
        self.assertEqual(sorted(env.get("required") or []), ["data", "success"], "Envelope required = [success, data].")
        self.assertEqual(((env.get("properties") or {}).get("success") or {}).get("enum"), [True], "Env.success [true].")
        self.assertEqual(((err.get("properties") or {}).get("success") or {}).get("enum"), [False], "Error.success [false].")
        env_data_ref = ((env.get("properties") or {}).get("data") or {}).get("$ref") or ""
        self.assertTrue(env_data_ref.endswith("/AllocationListPage"), f"Envelope.data.$ref PHẢI BỌC AllocationListPage (rows-key data.data[] double-data), got {env_data_ref}.")

