        self.assertIn("items", comm_page_keys, "CommissioningListPage rows-key = items (khác — chống copy-nhầm).")
        ops = {op.get("operationId") for _, _, op in _iter_operations(self.spec)}
        for opid in ("listAllocations", "listCommissioning", "getDueCalibrations"):
            self.assertIn(opid, ops, f"{opid} TỒN TẠI song song (khác endpoint, khác NGUỒN).")


