        self.assertIn(_INTERNAL_AUDIT_LIST_SCHEMA_REF, refs, f"oneOf thiếu nhánh success Env: {refs}")
        self.assertIn(_ERROR_SCHEMA_REF, refs, f"oneOf thiếu nhánh Error: {refs}")
        self.assertNotIn("discriminator", comp_sch, "KHÔNG discriminator — Decision-B closed-schema route-by-VALUE body.success.")
        env = self._schema("InternalAuditListEnvelope")
