    @classmethod
    def setUpClass(cls):
        cls.spec = _load_spec() if _MOBILE_YAML.exists() else None

    def setUp(self):
        if self.spec is None:
            self.skipTest("Thiếu yaml mobile spec.")

    def _op(self):
        return ((self.spec.get("paths") or {}).get(_SUBMIT_BASELINE_PATH) or {}).get("post") or {}

    def _schema(self, name):
        return ((self.spec.get("components") or {}).get("schemas") or {}).get(name) or {}

    def _resolve(self, ref):
        if not ref or not ref.startswith("#/"):
            return None
        cur = self.spec
        for raw in ref[2:].split("/"):
            part = raw.replace("~1", "/").replace("~0", "~")
            if isinstance(cur, dict) and part in cur:
                cur = cur[part]
            else:
                return None
        return cur

    @staticmethod
    def _collect_refs(node, acc):
        if isinstance(node, dict):
            for k, v in node.items():
                if k == "$ref" and isinstance(v, str):
                    acc.append(v)
                else:
                    TestMobileSubmitBaselineChecklist._collect_refs(v, acc)
        elif isinstance(node, list):
            for it in node:
                TestMobileSubmitBaselineChecklist._collect_refs(it, acc)

