        self.assertEqual(set(props.keys()), _PM_DASHBOARD_KPIS_PROPS,
                         f"props PHẢI EXACT 7 {_PM_DASHBOARD_KPIS_PROPS} (return-dict @imm08.py:1285-1298): {sorted(props.keys())}.")
        self.assertEqual(len(props), 7, "PHẢI đúng 7 prop (0 thừa/thiếu).")
        self.assertEqual(sorted(kpis.get("required") or []), sorted(_PM_DASHBOARD_KPIS_REQUIRED),
                         f"required PHẢI EXACT 6 {sorted(_PM_DASHBOARD_KPIS_REQUIRED)} (always-emit @source).")
        # compliance_rate_pct nullable:true ∧ ∉ required (None khi total_scheduled==0 @:1288).
        crp = props.get("compliance_rate_pct") or {}
        self.assertTrue(crp.get("nullable"),
                        "compliance_rate_pct PHẢI nullable:true (None khi total_scheduled==0 @imm08.py:1288).")
        self.assertNotIn("compliance_rate_pct", kpis.get("required") or [],
                         "compliance_rate_pct PHẢI ∉ required (nullable — None hợp lệ).")
        # nullable-set EXACT {compliance_rate_pct}.
        actual_nullable = {p for p, d in props.items() if d.get("nullable") is True}
        self.assertEqual(actual_nullable, _PM_DASHBOARD_KPIS_NULLABLE,
                         f"nullable-set PHẢI EXACT {{compliance_rate_pct}}: {sorted(actual_nullable)}.")
        # required ∩ nullable == ∅ ; required ∪ nullable phủ ĐỦ 7 prop.
        self.assertEqual(set(_PM_DASHBOARD_KPIS_REQUIRED) & _PM_DASHBOARD_KPIS_NULLABLE, set(),
                         "required (always-emit) ∩ nullable PHẢI == ∅.")
        self.assertEqual(set(_PM_DASHBOARD_KPIS_REQUIRED) | _PM_DASHBOARD_KPIS_NULLABLE,
                         _PM_DASHBOARD_KPIS_PROPS, "required ∪ nullable PHẢI phủ ĐỦ 7 prop.")
        # type grounded return-dict (5 count integer + avg_days_late/compliance_rate_pct number).
        for pname, expected_type in _PM_DASHBOARD_KPIS_TYPES.items():
            self.assertEqual((props.get(pname) or {}).get("type"), expected_type,
                             f"{pname} PHẢI type {expected_type} (grounded @services/imm08.py:1285-1298).")
        # 0 boolean/int-enum[0,1] (KHÔNG Check field trong 7 kpis).
        for pname, pdef in props.items():
            self.assertNotEqual(pdef.get("type"), "boolean",
                                f"{pname} KHÔNG được boolean (0 Check field — né int-vs-bool LL-BE-52).")
            self.assertNotEqual(pdef.get("enum"), [0, 1],
                                f"{pname} KHÔNG được integer enum[0,1] (0 Check field trong 7 kpis).")

