    def test_mob_oas_calkpi_i_naming_guard_no_collision(self):
        """(i) naming-guard — {CalibrationKpis, CalibrationKpisData, CalibrationKpisEnvelope} ∩ schema/param
        sẵn có == ∅; CalibrationKpis* ≠ Calibration/CalibrationDetail hiện hữu; 0 dangling $ref."""
        all_schemas = set(self._schemas().keys())
        new_fam = {_CALIBRATION_KPIS_SCHEMA, _CALIBRATION_KPIS_DATA_SCHEMA, _CALIBRATION_KPIS_ENVELOPE_SCHEMA}
        self.assertTrue(new_fam <= all_schemas,
                        f"Thiếu schema CR-31b: {sorted(new_fam - all_schemas)}.")
        # CalibrationKpis* family = ĐÚNG 3 schema (chống trùng tên ngoài ý muốn).
        cal_kpis_fam = {s for s in all_schemas if s.startswith("CalibrationKpis")}
        self.assertEqual(cal_kpis_fam, new_fam,
                         f"CalibrationKpis* family PHẢI ĐÚNG 3 schema CR-31b: {sorted(cal_kpis_fam)}.")
        # KHÔNG đụng Calibration/CalibrationDetail hiện hữu (enum-trùng-tên ≠ domain).
        for existing in ("Calibration", "CalibrationDetail", "CalibrationList",
                         "CalibrationListItem", "CalibrationDetailEnvelope"):
            self.assertNotIn(existing, new_fam,
                             f"CalibrationKpis* KHÔNG được = {existing} (schema hiện hữu khác domain).")
        # param namespace: 3 schema-name KHÔNG đụng tên parameters component.
        params_comp = set(((self.spec.get("components") or {}).get("parameters") or {}).keys())
        self.assertEqual(new_fam & params_comp, set(),
                         f"schema-name PHẢI ∩ parameters-component == ∅: {sorted(new_fam & params_comp)}.")
        dangling = sorted({r for r in _collect_refs(self.spec) if not _resolve_pointer(r, self.spec)})
        self.assertEqual(dangling, [], f"PHẢI 0 dangling $ref sau bồi getCalibrationKpis: {dangling}")


