    def test_mob_oas_repkpi_i_symmetry_slots(self):
        """(i) ∈ _MVP_BUSINESS_PATHS ∧ _PATHS_REQUIRE_401 ∧ _PATHS_REQUIRE_403 ∧ _MVP_READ_ENVELOPE
        (symmetry set); response slot CHỈ {200,401,403}; 401→Unauthorized401 + 403→Forbidden."""
        self.assertIn(_REPAIR_KPIS_PATH, _MVP_BUSINESS_PATHS, "PHẢI ∈ _MVP_BUSINESS_PATHS (401/403 symmetry).")
        self.assertIn(_REPAIR_KPIS_PATH, _PATHS_REQUIRE_401, "PHẢI ∈ _PATHS_REQUIRE_401.")
        self.assertIn(_REPAIR_KPIS_PATH, _PATHS_REQUIRE_403, "PHẢI ∈ _PATHS_REQUIRE_403.")
        self.assertIn(_REPAIR_KPIS_PATH, _MVP_READ_ENVELOPE, "PHẢI ∈ _MVP_READ_ENVELOPE (inline oneOf read-path).")
        self.assertEqual(_MVP_READ_ENVELOPE[_REPAIR_KPIS_PATH], _REPAIR_KPIS_ENVELOPE_SCHEMA_REF,
                         "_MVP_READ_ENVELOPE[getRepairKpis] PHẢI trỏ RepairKpisEnvelope ref.")
        ops = {path: op for path, _, op in _iter_operations(self.spec)}
        with_401 = {p for p, op in ops.items() if "401" in (op.get("responses") or {}) and p not in (_AUTH_PATHS | _ALLOW_GUEST_PATHS)}
        with_403 = {p for p, op in ops.items() if "403" in (op.get("responses") or {}) and p not in (_AUTH_PATHS | _ALLOW_GUEST_PATHS)}
        self.assertEqual(with_401, set(_PATHS_REQUIRE_403), "Tập 401 (trừ auth) == _PATHS_REQUIRE_403 (symmetry).")
        self.assertEqual(with_403, set(_PATHS_REQUIRE_403), "Tập 403 (trừ auth) == _PATHS_REQUIRE_403 (symmetry).")
        resps = (self._op().get("responses") or {})
        self.assertEqual(sorted(resps.keys()), ["200", "401", "403"],
                         f"response slot PHẢI CHỈ {{200,401,403}} (lỗi tham-số/nội-bộ trên HTTP-200 nhánh Error): {sorted(resps.keys())}")
        self.assertEqual((resps.get("401") or {}).get("$ref"), _UNAUTHORIZED401_RESP_REF, "401 PHẢI $ref Unauthorized401.")
        self.assertEqual((resps.get("403") or {}).get("$ref"), _FORBIDDEN_RESP_REF, "403 PHẢI $ref Forbidden.")

    def test_mob_oas_repkpi_j_naming_guard_no_collision(self):
        """(j) naming-guard — RepairKpis* family EXACT 3 + RepairRootCauseItem riêng; ∩ (RepairWorkOrder*/
        RepairAction* hiện hữu) == ∅; ∩ param-component == ∅; 0 dangling $ref."""
        all_schemas = set(self._schemas().keys())
        new_fam = {_REPAIR_KPIS_SCHEMA, _REPAIR_KPIS_DATA_SCHEMA, _REPAIR_KPIS_ENVELOPE_SCHEMA,
                   _REPAIR_ROOT_CAUSE_ITEM_SCHEMA}
        self.assertTrue(new_fam <= all_schemas,
                        f"Thiếu schema CR-31c: {sorted(new_fam - all_schemas)}.")
        # RepairKpis* family = ĐÚNG 3 schema (RepairRootCauseItem KHÔNG prefix RepairKpis — chống trùng tên).
        rep_kpis_fam = {s for s in all_schemas if s.startswith("RepairKpis")}
        self.assertEqual(rep_kpis_fam, {_REPAIR_KPIS_SCHEMA, _REPAIR_KPIS_DATA_SCHEMA, _REPAIR_KPIS_ENVELOPE_SCHEMA},
                         f"RepairKpis* family PHẢI ĐÚNG 3 schema CR-31c: {sorted(rep_kpis_fam)}.")
        # KHÔNG đụng RepairWorkOrder*/RepairAction* hiện hữu (enum-trùng-tên ≠ domain).
        for existing in ("RepairWorkOrderListItem", "RepairWorkOrderDetail", "RepairWorkOrderList",
                         "RepairWorkOrderListEnvelope", "RepairWorkOrderDetailEnvelope",
                         "RepairActionResponse", "RepairActionEnvelope"):
            self.assertNotIn(existing, new_fam,
                             f"RepairKpis*/RepairRootCauseItem KHÔNG được = {existing} (schema hiện hữu khác domain).")
        # param namespace: 4 schema-name KHÔNG đụng tên parameters component.
        params_comp = set(((self.spec.get("components") or {}).get("parameters") or {}).keys())
        self.assertEqual(new_fam & params_comp, set(),
                         f"schema-name PHẢI ∩ parameters-component == ∅: {sorted(new_fam & params_comp)}.")
        dangling = sorted({r for r in _collect_refs(self.spec) if not _resolve_pointer(r, self.spec)})
        self.assertEqual(dangling, [], f"PHẢI 0 dangling $ref sau bồi getRepairKpis: {dangling}")


